INSERT INTO public.recipes (id, nom, description, saison, mois, mois_numero, semaine, jour, tag, categorie, theme_special, portions, estimated_time, difficulty, image_url, ingredients, instructions, astuce, cuisson_micro_ondes, sans_four, source, source_pdf, source_page, dietary_tags, main_ingredients, equipment, canonical_ingredients_status)
VALUES
  ('city-cafe-veggie-american-pot-pie', 'Veggie American Pot Pie', 'Veggie American Pot Pie préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'hiver', 'février', 2, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 75, 'facile', 'https://images.pexels.com/photos/39070796/pexels-photo-39070796.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pâte brisée","quantity":"300","unit":"g","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Œufs","quantity":"4","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Crème","quantity":"120","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Tomates","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Mozzarella","quantity":"120","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Basilic","quantity":"300","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Préchauffer le four à 190 °C. Préparer la garniture pâte brisée, œufs, crème et cuire au préalable les légumes humides dans une poêle pour évacuer leur eau.","Foncer le moule ou la plaque avec la pâte; piquer le fond. Mélanger les œufs, la crème et le fromage, puis assaisonner.","Répartir la garniture, verser l’appareil ou la sauce et enfourner 30 à 40 minutes jusqu’à ce que la pâte soit dorée et le centre pris.","Laisser reposer 8 minutes avant de couper; accompagner de la salade ou des herbes prévues."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, false, 'broco-chou', null, null, array['végétarien']::text[], array['pâte brisée', 'œufs', 'crème']::text[], array['four', 'saladier', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-cari-d-oeufs-et-achar-de-legumes', 'Cari d’œufs et achar de légumes', 'Cari d’œufs et achar de légumes préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/24186308/pexels-photo-24186308.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Carottes","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bouillon","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Thym","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Éplucher et couper les oignons et les carottes en morceaux réguliers; sécher et assaisonner la viande si le plat en contient. Faire chauffer l’huile dans une cocotte.","Faire dorer la viande par petites quantités, puis ajouter oignons, carottes et ail et cuire 4 minutes. Pour une version végétarienne, faire simplement revenir les légumes et les légumineuses.","Ajouter le bouillon et les aromates, couvrir et mijoter doucement jusqu’à ce que les ingrédients soient tendres (30 à 90 minutes selon le plat); remuer et ajouter un peu d’eau si nécessaire.","Cuire l’accompagnement séparément, goûter la sauce, rectifier l’assaisonnement et servir chaud."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['oignons', 'carottes', 'ail']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-omelette-espagnole-facon-tortilla', 'Omelette espagnole façon tortilla', 'Omelette espagnole façon tortilla préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/21327969/pexels-photo-21327969.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Tortillas","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Œufs","quantity":"2","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Beurre","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Crème","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer les légumes tortillas et les couper finement. Faire revenir les garnitures dans une poêle avec le beurre jusqu’à ce qu’elles soient tendres.","Battre les œufs avec la crème, le sel et le poivre. Verser sur la garniture chaude.","Cuire à feu doux en ramenant les bords vers le centre jusqu’à ce que l’omelette soit prise mais encore moelleuse; cuire complètement les œufs si la recette le demande.","Ajouter le fromage et les herbes, plier ou dresser les œufs et servir immédiatement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['tortillas']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-brioche-toastee-duxelles-de-champignons-et-oeuf-au-plat', 'Brioche toastée, duxelles de champignons et œuf au plat', 'Brioche toastée, duxelles de champignons et œuf au plat préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'très facile', 'https://images.pexels.com/photos/28292002/pexels-photo-28292002.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Champignons de Paris","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Œufs","quantity":"2","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Brioche","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Pain","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Salade","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer les garnitures champignons de paris, œufs, brioche; laver et essorer les légumes, puis cuire toute protéine crue à cœur dans une poêle chaude.","Mélanger les éléments de sauce et assaisonner. Trancher le pain; le toaster ou le réchauffer à la poêle jusqu’à ce qu’il soit doré.","Monter le sandwich avec la sauce, les éléments chauds puis les légumes frais. Pour un fromage à gratiner, passer 3 à 5 minutes sous le gril.","Couper en deux et servir aussitôt, avec la garniture prévue."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['champignons de paris', 'œufs', 'brioche']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-croustillant-caprese', 'Croustillant caprese', 'Croustillant caprese préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 30, 'très facile', 'https://images.pexels.com/photos/18635876/pexels-photo-18635876.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pommes de terre","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Œufs","quantity":"2","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Fromage frais","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Tomates","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Mozzarella","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Basilic","quantity":"150","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Préchauffer le four à 190 °C. Préparer la garniture pommes de terre, œufs, fromage frais et cuire au préalable les légumes humides dans une poêle pour évacuer leur eau.","Foncer le moule ou la plaque avec la pâte; piquer le fond. Mélanger les œufs, la crème et le fromage, puis assaisonner.","Répartir la garniture, verser l’appareil ou la sauce et enfourner 30 à 40 minutes jusqu’à ce que la pâte soit dorée et le centre pris.","Laisser reposer 8 minutes avant de couper; accompagner de la salade ou des herbes prévues."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, false, 'broco-chou', null, null, array['végétarien']::text[], array['pommes de terre', 'œufs', 'fromag