  ('city-cafe-welsh-du-nord', 'Welsh du Nord', 'Welsh du Nord préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'hiver', 'janvier', 1, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 25, 'très facile', 'https://images.pexels.com/photos/38169158/pexels-photo-38169158.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pain","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Salade","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Mozzarella","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Basilic","quantity":"150","unit":"g","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Mayonnaise","quantity":"150","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer les garnitures pain, salade, tomates; laver et essorer les légumes, puis cuire toute protéine crue à cœur dans une poêle chaude.","Mélanger les éléments de sauce et assaisonner. Trancher le pain; le toaster ou le réchauffer à la poêle jusqu’à ce qu’il soit doré.","Monter le sandwich avec la sauce, les éléments chauds puis les légumes frais. Pour un fromage à gratiner, passer 3 à 5 minutes sous le gril.","Couper en deux et servir aussitôt, avec la garniture prévue."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['pain', 'salade', 'tomates']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-dahl-cremeux-de-lentilles-corail-courge-et-blettes', 'Dahl crémeux de lentilles corail, courge et blettes', 'Dahl crémeux de lentilles corail, courge et blettes préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 55, 'facile', 'https://images.pexels.com/photos/6544373/pexels-photo-6544373.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Butternut","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Blettes","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Lentilles","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Lentilles corail","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Carottes","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bouillon","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Thym","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"}]'::jsonb, '["Éplucher et couper les oignons et les carottes en morceaux réguliers; sécher et assaisonner la viande si le plat en contient. Faire chauffer l’huile dans une cocotte.","Faire dorer la viande par petites quantités, puis ajouter oignons, carottes et ail et cuire 4 minutes. Pour une version végétarienne, faire simplement revenir les légumes et les légumineuses.","Ajouter le bouillon et les aromates, couvrir et mijoter doucement jusqu’à ce que les ingrédients soient tendres (30 à 90 minutes selon le plat); remuer et ajouter un peu d’eau si nécessaire.","Cuire l’accompagnement séparément, goûter la sauce, rectifier l’assaisonnement et servir chaud."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['butternut', 'blettes', 'lentilles', 'lentilles corail']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-courge-farcie-au-quinoa-et-fromage-de-chevre', 'Courge farcie au quinoa et fromage de chèvre', 'Courge farcie au quinoa et fromage de chèvre préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 70, 'facile', 'https://images.pexels.com/photos/4899793/pexels-photo-4899793.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Butternut","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Quinoa","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Chèvre","quantity":"150","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Oignons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer et couper les légumes butternut, quinoa, chèvre en morceaux réguliers. Préchauffer le four à 200 °C si la recette prévoit une cuisson rôtie.","Faire revenir les aromates dans une casserole ou une grande poêle avec l’huile, puis ajouter les légumes et les légumineuses.","Ajouter un fond d’eau ou de bouillon, couvrir et cuire 15 à 25 minutes jusqu’à tendreté; mélanger régulièrement et compléter le liquide si nécessaire.","Assaisonner, ajouter les herbes et le fromage prévus, puis servir avec l’accompagnement indiqué."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['butternut', 'quinoa', 'chèvre']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-poke-bowl-sain-au-saumon-avocat-et-legumes-croquants', 'Poke bowl sain au saumon, avocat et légumes croquants', 'Poke bowl sain au saumon, avocat et légumes croquants préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'juillet', 7, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/36555140/pexels-photo-36555140.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Avocats","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Saumon","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Citrons","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Persil","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Sécher le poisson et préparer les garnitures avocats, saumon; préchauffer le four à 190 °C si la cuisson est au four.","Cuire les accompagnements séparément: démarrer les pommes de terre ou les céréales dans une casserole d’eau salée.","Saisir le poisson dans une poêle huilée 2 à 3 min par face selon l’épaisseur, ou le cuire au four 10 à 15 min jusqu’à ce que sa chair soit opaque et se détache.","Préparer la sauce avec les aromates et le citron, puis servir immédiatement avec le poisson et l’accompagnement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['poisson']::text[], array['avocats', 'saumon']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-tajine-vert-de-legumes-et-pois-chiches', 'Tajine vert de légumes et pois chiches', 'Tajine vert de légumes et pois chiches préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'printemps', 'mai', 5, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 70, 'facile', 'https://images.pexels.com/photos/998244/pexels-photo-998244.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Pois chiches","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Oignons","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Carottes","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Ail","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Bouillon","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Thym","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épices et herbes aromatiques"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Éplucher et couper les oignons et les carottes en morceaux réguliers; sécher et assaisonner la viande si le plat en contient. Faire chauffer l’huile dans une cocotte.","Faire dorer la viande par petites quantités, puis ajouter oignons, carottes et ail et cuire 4 minutes. Pour une version végétarienne, faire simplement revenir les légumes et les légumineuses.","Ajouter le bouillon et les aromates, couvrir et mijoter doucement jusqu’à ce que les ingrédients soient tendres (30 à 90 minutes selon le plat); remuer et ajouter un peu d’eau si nécessaire.","Cuire l’accompagnement séparément, goûter la sauce, rectifier l’assaisonnement et servir chaud."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['pois chiches']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-patate-douce-farcie-a-la-duxelles-de-champignons-et-oeuf-mollet', 'Patate douce farcie à la duxelles de champignons et œuf mollet', 'Patate douce farcie à la duxelles de champignons et œuf mollet préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 65, 'facile', 'https://images.pexels.com/photos/35546716/pexels-photo-35546716.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Champignons de Paris","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Œufs","quantity":"2","unit":"pièces","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Beurre","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Crème","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer les légumes champignons de paris, œufs et les couper finement. Faire revenir les garnitures dans une poêle avec le beurre jusqu’à ce qu’elles soient tendres.","Battre les œufs avec la crème, le sel et le poivre. Verser sur la garniture chaude.","Cuire à feu doux en ramenant les bords vers le centre jusqu’à ce que l’omelette soit prise mais encore moelleuse; cuire complètement les œufs si la recette le demande.","Ajouter le fromage et les herbes, plier ou dresser les œufs et servir immédiatement."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['champignons de paris', 'œufs']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-ramen-vegetarien-au-miso-et-tahini', 'Ramen végétarien au miso et tahini', 'Ramen végétarien au miso et tahini préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'hiver', 'janvier', 1, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 40, 'facile', 'https://images.pexels.com/photos/4224212/pexels-photo-4224212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Tahini","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Miso","quantity":"150","unit":"g","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Pâtes","quantity":"160","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Ail","quantity":"1","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Porter une grande casserole d’eau salée à ébullition et cuire les pâtes selon leur emballage; réserver une louche d’eau de cuisson.","Pendant ce temps, préparer et couper les garnitures tahini, miso. Faire revenir les éléments aromatiques dans une poêle avec l’huile.","Ajouter les ingrédients principaux et cuire jusqu’à tendreté; incorporer la sauce ou le fromage prévu et détendre avec un peu d’eau de cuisson.","Mélanger avec les pâtes égouttées, rectifier l’assaisonnement et servir aussitôt avec la garniture restante."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['tahini', 'miso']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
  ('city-cafe-lasagnes-gourmandes-au-potimarron-et-a-la-roquette', 'Lasagnes gourmandes au potimarron et à la roquette', 'Lasagnes gourmandes au potimarron et à la roquette préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'automne', 'octobre', 10, null, null, 'déjeuner/dîner', 'salé', null, '4 personnes', 75, 'facile', 'https://images.pexels.com/photos/31119078/pexels-photo-31119078.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Potimarron","quantity":"300","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Pâtes","quantity":"320","unit":"g secs","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Ail","quantity":"2","unit":"pièces","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Huile d''olive","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Porter une grande casserole d’eau salée à ébullition et cuire les pâtes selon leur emballage; réserver une louche d’eau de cuisson.","Pendant ce temps, préparer et couper les garnitures potimarron. Faire revenir les éléments aromatiques dans une poêle avec l’huile.","Ajouter les ingrédients principaux et cuire jusqu’à tendreté; incorporer la sauce ou le fromage prévu et détendre avec un peu d’eau de cuisson.","Mélanger avec les pâtes égouttées, rectifier l’assaisonnement et servir aussitôt avec la garniture restante."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['végétarien']::text[], array['potimarron']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified')
