-- City Café batch 05: recettes. Generated from city-cafe-recipes-batch-05.json.
BEGIN;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  nom = EXCLUDED.nom,
  description = EXCLUDED.description,
  saison = EXCLUDED.saison,
  mois = EXCLUDED.mois,
  mois_numero = EXCLUDED.mois_numero,
  semaine = EXCLUDED.semaine,
  jour = EXCLUDED.jour,
  tag = EXCLUDED.tag,
  categorie = EXCLUDED.categorie,
  theme_special = EXCLUDED.theme_special,
  portions = EXCLUDED.portions,
  estimated_time = EXCLUDED.estimated_time,
  difficulty = EXCLUDED.difficulty,
  image_url = EXCLUDED.image_url,
  ingredients = EXCLUDED.ingredients,
  instructions = EXCLUDED.instructions,
  astuce = EXCLUDED.astuce,
  cuisson_micro_ondes = EXCLUDED.cuisson_micro_ondes,
  sans_four = EXCLUDED.sans_four,
  source = EXCLUDED.source,
  source_pdf = EXCLUDED.source_pdf,
  source_page = EXCLUDED.source_page,
  dietary_tags = EXCLUDED.dietary_tags,
  main_ingredients = EXCLUDED.main_ingredients,
  equipment = EXCLUDED.equipment,
  canonical_ingredients_status = EXCLUDED.canonical_ingredients_status;

-- Keep ingredient JSON category labels aligned with the canonical ingredient catalog.
UPDATE public.recipes AS recipe
SET ingredients = (
  SELECT jsonb_agg(jsonb_set(item.ingredient, '{category}', to_jsonb(canonical.category), true) ORDER BY item.ordinality)
  FROM jsonb_array_elements(recipe.ingredients) WITH ORDINALITY AS item(ingredient, ordinality)
  JOIN public.ingredients AS canonical ON canonical.name = item.ingredient->>'name'
)
WHERE recipe.id IN ('city-cafe-veggie-american-pot-pie', 'city-cafe-cari-d-oeufs-et-achar-de-legumes', 'city-cafe-omelette-espagnole-facon-tortilla', 'city-cafe-brioche-toastee-duxelles-de-champignons-et-oeuf-au-plat', 'city-cafe-croustillant-caprese', 'city-cafe-huevos-rancheros-et-salsa-verde', 'city-cafe-omelette-a-la-courge-aux-champignons-et-au-fromage-frais', 'city-cafe-gua-bao-au-tofu-et-legumes-croquants', 'city-cafe-oeufs-a-la-florentine', 'city-cafe-tartine-a-l-avocat-tomate-mozzarella-et-sauce-vierge', 'city-cafe-croquettes-de-petits-pois-feta-et-zaatar', 'city-cafe-brioche-perdue-salee-caviar-d-aubergine-et-oeuf-au-plat', 'city-cafe-nouilles-sautees-aux-legumes-d-ete', 'city-cafe-pain-croustillant-gratine-au-cheddar', 'city-cafe-curry-de-pois-casses-epinards-et-patate-douce-oeuf-au-plat', 'city-cafe-chou-fleur-caramelise-au-sesame-et-riz-a-sushi', 'city-cafe-couscous-vegetarien-aux-saveurs-orientales', 'city-cafe-lasagnes-vegetariennes-automnales', 'city-cafe-welsh-du-nord', 'city-cafe-dahl-cremeux-de-lentilles-corail-courge-et-blettes', 'city-cafe-courge-farcie-au-quinoa-et-fromage-de-chevre', 'city-cafe-poke-bowl-sain-au-saumon-avocat-et-legumes-croquants', 'city-cafe-tajine-vert-de-legumes-et-pois-chiches', 'city-cafe-patate-douce-farcie-a-la-duxelles-de-champignons-et-oeuf-mollet', 'city-cafe-ramen-vegetarien-au-miso-et-tahini', 'city-cafe-lasagnes-gourmandes-au-potimarron-et-a-la-roquette');

-- Keep recipe image choices in sync if reviewed later.
UPDATE public.recipes AS recipe
SET image_url = image.image_url
FROM (VALUES
  ('city-cafe-veggie-american-pot-pie', 'https://images.pexels.com/photos/39070796/pexels-photo-39070796.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-cari-d-oeufs-et-achar-de-legumes', 'https://images.pexels.com/photos/24186308/pexels-photo-24186308.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-omelette-espagnole-facon-tortilla', 'https://images.pexels.com/photos/21327969/pexels-photo-21327969.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-brioche-toastee-duxelles-de-champignons-et-oeuf-au-plat', 'https://images.pexels.com/photos/28292002/pexels-photo-28292002.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
