  ('city-cafe-huevos-rancheros-et-salsa-verde', 'https://images.pexels.com/photos/31823016/pexels-photo-31823016.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-omelette-a-la-courge-aux-champignons-et-au-fromage-frais', 'https://images.pexels.com/photos/27359373/pexels-photo-27359373.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-gua-bao-au-tofu-et-legumes-croquants', 'https://images.pexels.com/photos/14855134/pexels-photo-14855134.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-oeufs-a-la-florentine', 'https://images.pexels.com/photos/12268531/pexels-photo-12268531.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-tartine-a-l-avocat-tomate-mozzarella-et-sauce-vierge', 'https://images.pexels.com/photos/29380178/pexels-photo-29380178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-croquettes-de-petits-pois-feta-et-zaatar', 'https://images.pexels.com/photos/33217883/pexels-photo-33217883.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
