  ('city-cafe-nouilles-sautees-aux-legumes-d-ete', 'https://images.pexels.com/photos/8935245/pexels-photo-8935245.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-pain-croustillant-gratine-au-cheddar', 'https://images.pexels.com/photos/33042510/pexels-photo-33042510.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-curry-de-pois-casses-epinards-et-patate-douce-oeuf-au-plat', 'https://images.pexels.com/photos/9213999/pexels-photo-9213999.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-chou-fleur-caramelise-au-sesame-et-riz-a-sushi', 'https://images.pexels.com/photos/9213991/pexels-photo-9213991.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-couscous-vegetarien-aux-saveurs-orientales', 'https://images.pexels.com/photos/19824910/pexels-photo-19824910.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-lasagnes-vegetariennes-automnales', 'https://images.pexels.com/photos/37679127/pexels-photo-37679127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-welsh-du-nord', 'https://images.pexels.com/photos/38169158/pexels-photo-38169158.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-dahl-cremeux-de-lentilles-corail-courge-et-blettes', 'https://images.pexels.com/photos/6544373/pexels-photo-6544373.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
