  ('city-cafe-tajine-vert-de-legumes-et-pois-chiches', 'https://images.pexels.com/photos/998244/pexels-photo-998244.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-patate-douce-farcie-a-la-duxelles-de-champignons-et-oeuf-mollet', 'https://images.pexels.com/photos/35546716/pexels-photo-35546716.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-ramen-vegetarien-au-miso-et-tahini', 'https://images.pexels.com/photos/4224212/pexels-photo-4224212.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-lasagnes-gourmandes-au-potimarron-et-a-la-roquette', 'https://images.pexels.com/photos/31119078/pexels-photo-31119078.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
) AS image(id, image_url)
WHERE recipe.id = image.id;

COMMIT;
